import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`ad-copy-rewrite`,heroTitle:`Rewrite your ad copy in minutes`,heroSubtitle:`Perplexity Computer studies your offer, learns the conversion angle, and produces new paid social copy variations automatically.`,inputUrlCta:`Rewrite my ads`,inputUrlPlaceholder:`www.yourlandingpage.com`,inputUrlPrefill:`Go to {url} and use it as the landing page to rewrite paid social ad copy. Extract the offer, audience, objections, proof, and CTA. Analyze direct-response patterns relevant to this market, then create 10 Facebook and Instagram ad concepts with primary text, headline, description, and hook angle. Use frameworks like PAS, AIDA, and Before-After-Bridge where appropriate. Include which audience or awareness level each concept is best for and note the core message testing themes.`,heroOverlaySteps:[`Pulling the offer, audience, and proof from your landing page`,`Mapping objections, desire states, and direct-response angles`,`Writing multiple ad concepts for different hooks and audiences`,`Fresh paid social copy variations ready to test in Meta Ads`],generatingSteps:[`Opening {url} to understand the offer, CTA, and conversion path`,`Designing an agent to map audience objections and direct-response angles`,`Configuring multi-angle ad copy generation for Facebook and Instagram placements`,`Preparing a structured testing pack with concept notes and creative directions`],featureSectionTitle:`From landing page to test-ready ads`,featureCardTitles:[`Connects to your growth stack`,`Concepts built for testing`],featureCardDescriptions:[`Computer separates offer analysis, audience strategy, copywriting, and testing structure so each part gets handled by the best model.`,`Docs, Sheets, Notion, and campaign planning tools stay connected so copy review and launch move faster.`,`You get angle-based ad variants, suggested hooks, headlines, and descriptions organized for rapid iteration inside your ad account.`],capabilitySectionTitle:`Your direct-response copy desk, on demand`,capabilitySectionSubtitle:`Paste your page URL and come back to a fresh batch of ads built for Meta testing.`,capabilityCards:[{title:`Offer Breakdown`,description:`Computer can turn your page into a clear message hierarchy of promise, proof, friction, objections, and CTA.`},{title:`Angle Development`,description:`Computer can generate multiple hooks and awareness-level angles so you are not stuck testing the same creative idea repeatedly.`},{title:`Copy Variations`,description:`Computer can write ad primary text, headlines, and descriptions that fit different stages of the funnel and different audience intents.`},{title:`Connect Your Tools`,description:`Computer can push drafts into Sheets, briefs, and review workflows so your media and creative teams stay aligned.`},{title:`Remember What Works`,description:`Computer can keep track of your approved claims, brand tone, and winning themes for future copy refreshes.`},{title:`Keep Creative Fresh`,description:`Computer can propose new iterations on a schedule so your paid social copy does not stall out from fatigue.`}]});export{t as default};
